import type { CollectionEntry } from 'astro:content';

export interface HandsOnNote {
  id: string;
  date: string;
  tool: string;
  /** Use-case page this note is filed under. Null when no existing job fits. */
  useCaseSlug: string | null;
  /** A phrase that must already appear on the use-case page, or in this note when it has no page. */
  anchor: string;
  /** One dated sentence, copied only from `tested` and `limits`. */
  quote: string;
  tested: string;
  limits: string;
}

/** The dated line for a pick, when this page has exactly one note on that day. */
export function handsOnQuote(useCaseSlug: string, isoDay: string): string | null {
  const matches = handsOnNotes.filter((note) => note.useCaseSlug === useCaseSlug && note.date === isoDay);
  return matches.length === 1 ? matches[0].quote : null;
}

