const COVERED = ['research-and-summarise-sources', 'translate-a-document', 'proofread-and-edit', 'design-logos-and-graphics', 'check-if-an-image-is-ai', 'analyse-a-spreadsheet', 'write-posts-and-emails', 'design-an-app-screen', 'vibe-code-an-mvp', 'ai-voiceover', 'cut-out-a-product-photo', 'turn-notes-into-flashcards', 'keep-a-citation-library', 'automate-small-business-admin', 'run-marketing-campaigns', 'check-if-writing-is-ai', 'upscale-a-low-resolution-image'];

function pageText(entry: CollectionEntry<'use-cases'>): string {
  return `${entry.data.testNotes}\n${entry.body ?? ''}`;
}

/** Fail the build if this list and the use-case pages disagree. */
export function assertHandsOnCoverage(entries: CollectionEntry<'use-cases'>[]): void {
  const withNotes = entries
    .filter((entry) => {
      const text = pageText(entry);
      return /Hands-on note|Hands-on test \(/.test(text) || Boolean(entry.data.topPick.handsOn) || Boolean(entry.data.budgetPick.handsOn) || Boolean(entry.data.avoid.handsOn);
    })
    .map((entry) => entry.id)
    .sort();
  const expected = [...COVERED].sort();
  if (withNotes.join('|') !== expected.join('|')) {
    throw new Error(`Hands-on coverage changed. Found: ${withNotes.join(', ') || '(none)'}. Expected: ${expected.join(', ')}.`);
  }
  for (const note of handsOnNotes) {
    if (!note.useCaseSlug) {
      const own = `${note.quote}\n${note.tested}\n${note.limits}`;
      if (!own.includes(note.anchor)) {
        throw new Error(`Hands-on note ${note.id} is missing its anchor.`);
      }
      continue;
    }
    const entry = entries.find((item) => item.id === note.useCaseSlug);
    if (!entry) throw new Error(`Hands-on note ${note.id} points at a missing use case.`);
    if (!pageText(entry).includes(note.anchor)) {
      throw new Error(`Hands-on note ${note.id} is not in ${note.useCaseSlug}.`);
    }
  }
}
